CREATE FUNCTION public.offsite_referencias() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT (offsite_admin() OR offsite_cadeira() IS NOT NULL) THEN RAISE EXCEPTION 'Sem permissão'; END IF; RETURN jsonb_build_object('cadeiras',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'nome',nome,'diretor_nome',diretor_nome,'diretor_user_id',diretor_user_id) ORDER BY nome),'[]') FROM mt_cadeiras WHERE ativo),'objetivos',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'codigo',codigo,'nome',descricao) ORDER BY codigo),'[]') FROM mt_objetivos),'kpis',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'codigo',codigo,'nome',nome,'objetivo_id',objetivo_id) ORDER BY codigo),'[]') FROM mt_indicadores WHERE origem='bsc' AND status='ativo'),'processos',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'nome',nome) ORDER BY nome),'[]') FROM processos WHERE ativo)); END $$;
REVOKE ALL ON FUNCTION public.offsite_referencias() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.offsite_referencias() TO authenticated;